using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Newtonsoft.Json;
public static class InstallClothingFit {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string path="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";const string meshPath="Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_Clearance.asset";
 var root=PrefabUtility.LoadPrefabContents(path);try{var cloth=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_Outfits_LOD0");var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_BodyBound.asset");var mesh=UnityEngine.Object.Instantiate(source);mesh.name="EthanV2_Outfit_Clearance";var offsets=JsonConvert.DeserializeObject<float[][]>(File.ReadAllText("Data/EthanV2/ClothingRepair/fit_offsets.json"));var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++){var d=offsets[i];vertices[i]+=cloth.transform.InverseTransformVector(root.transform.TransformVector(new Vector3(d[0],d[1],d[2])));}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();var existing=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,meshPath);cloth.sharedMesh=mesh;cloth.rootBone=root.transform;cloth.localBounds=new Bounds(new Vector3(0,1.1f,0),new Vector3(2.4f,2.4f,2.4f));PrefabUtility.SaveAsPrefabAsset(root,path);AssetDatabase.SaveAssets();return new{mesh=meshPath,bodyMask=false,vertices=mesh.vertexCount,shapes=mesh.blendShapeCount};}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
